import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertCircle, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Check, ChevronRight, CircleDot, Clock3, CloudSun, Database, Gauge, HeartPulse, Plus, Radio, Radiation as RadiationIcon, RefreshCw, ShieldAlert, Thermometer, Wind } from 'lucide-react';
import { Alert, api, canManageCrew, canRecord, canReviewAlerts, Crew, Environment, EXPIRY_KEY, formatDate, formatTime, freshness, json, latest, localInputTime, Measurement, number, pretty, Radiation, Snapshot, TOKEN_KEY, User, ViewProps } from '../lib';
import { ChartPoint, prepareChart } from './chartData';
import { hasOmittedActiveAlerts, snapshotWindow } from './snapshotWindow';
import { chartSegments, formatTrendAxis, formatTrendValue } from './trendChartGaps';
import { loadTrendHistory, TREND_RECORD_CAP, TrendHistory } from './trendHistory';
import { MissionBriefing } from './MissionBriefing';

const MissionOrbit = lazy(() => import('./MissionOrbit').then(module => ({ default: module.MissionOrbit })));

type Metric = { key: string; label: string; unit: string; short?: string };
const TELEMETRY: Metric[] = [
  { key: 'heart_rate', label: 'Heart rate', unit: 'bpm', short: 'HR' }, { key: 'bp_systolic', label: 'BP systolic', unit: 'mmHg', short: 'SYS' }, { key: 'bp_diastolic', label: 'BP diastolic', unit: 'mmHg', short: 'DIA' }, { key: 'spo2', label: 'Oxygen saturation', unit: '%', short: 'SpO₂' }, { key: 'respiratory_rate', label: 'Respiratory rate', unit: 'breaths/min', short: 'RESP' }, { key: 'temperature', label: 'Body temperature', unit: '°C', short: 'TEMP' }, { key: 'sleep', label: 'Sleep duration', unit: 'hours', short: 'SLEEP' }, { key: 'hydration', label: 'Hydration', unit: '%', short: 'HYDRATION' }, { key: 'weight', label: 'Weight', unit: 'kg', short: 'WEIGHT' }, { key: 'body_fat', label: 'Body fat', unit: '%', short: 'BODY FAT' },
];
const ENVIRONMENT: Metric[] = [
  { key: 'cabin_temperature', label: 'Cabin temperature', unit: '°C' }, { key: 'cabin_pressure', label: 'Cabin pressure', unit: 'kPa' }, { key: 'oxygen', label: 'Oxygen', unit: '%' }, { key: 'co2', label: 'Carbon dioxide', unit: 'ppm' }, { key: 'humidity', label: 'Humidity', unit: '%' }, { key: 'air_quality', label: 'Air quality', unit: 'index' }, { key: 'radiation', label: 'Ambient radiation', unit: 'mSv/h' },
];
const metricLabel = (key: string) => [...TELEMETRY, ...ENVIRONMENT].find(m => m.key === key)?.label || pretty(key);
const initials = (name: string) => name.split(/\s+/).map(s => s[0]).slice(0, 2).join('').toUpperCase();
const activeFor = (data: Snapshot, type: string, id?: string, metric?: string) => data.alerts.filter(a => !a.resolved && a.entity_type === type && (!id || a.entity_id === id) && (!metric || a.metric === metric));
const severityTone = (alerts: Alert[]) => alerts.some(a => a.severity === 'CRITICAL') ? 'red' : alerts.some(a => a.severity === 'WARNING') ? 'amber' : alerts.length ? 'cyan' : 'green';
const severityLabel = (alerts: Alert[]) => alerts.some(a => a.severity === 'CRITICAL') ? 'CRITICAL' : alerts.some(a => a.severity === 'WARNING') ? 'WARNING' : alerts.length ? 'INFORMATIONAL' : 'NO ACTIVE ALERTS';
const sortNewest = <T,>(rows: T[], get: (row: T) => string) => [...rows].sort((a, b) => Date.parse(get(b)) - Date.parse(get(a)));

function Heading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="page-heading"><div><div className="eyebrow"><span className="accent-line" /> {eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>;
}
function PanelTitle({ icon: Icon, title, subtitle, action }: { icon?: typeof Activity; title: string; subtitle?: string; action?: React.ReactNode }) {
  return <div className="panel-heading"><div className="panel-heading-main">{Icon && <Icon size={17} className="panel-icon" />}<div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div></div>{action}</div>;
}
function Status({ tone = 'muted', children }: { tone?: string; children: React.ReactNode }) { return <span className={`status status-${tone}`}><span className={`dot ${tone}-bg`} />{children}</span>; }
function Empty({ children }: { children: React.ReactNode }) { return <div className="empty-state">{children}</div>; }
function Fresh({ timestamp, staleMinutes }: { timestamp?: string; staleMinutes?: number }) { const state = freshness(timestamp, staleMinutes); return <span className={`freshness text-${state.tone}`}>{state.label}</span>; }
function Value({ record, digits = 1 }: { record?: { value: number; unit: string }; digits?: number }) { return <>{record && Number.isFinite(record.value) ? <>{number(record.value, digits)} <small>{record.unit}</small></> : <span className="missing-value">— <small>MISSING</small></span>}</>; }
function SectionAction({ children, onClick }: { children: React.ReactNode; onClick: () => void }) { return <button className="link-button" onClick={onClick}>{children} <ArrowRight size={14} /></button>; }
function latestMetric(data: Snapshot, crew: string, metric: string) { return latest(data.measurements.filter(m => m.crew_id === crew && m.metric === metric)); }
function latestEnv(data: Snapshot, metric: string) { return latest(data.environment.filter(m => m.metric === metric)); }
function CrewAvatar({ crew, index = 0 }: { crew: Crew; index?: number }) { return <div className={`crew-avatar avatar-${index % 4}`} aria-hidden="true">{initials(crew.name)}</div>; }

export function DashboardView({ data, refresh, navigate }: ViewProps & { navigate: (module: string, crewId?: string) => void }) {
  const critical = data.alerts.filter(a => !a.resolved && a.severity === 'CRITICAL');
  const active = data.alerts.filter(a => !a.resolved);
  const alertWindow = snapshotWindow(data, 'alerts');
  const activeCount = alertWindow?.active ?? active.length;
  const criticalCount = alertWindow?.active_critical ?? critical.length;
  const alertsIncomplete = hasOmittedActiveAlerts(data);
  const cabin = latestEnv(data, 'cabin_temperature');
  const envAlerts = activeFor(data, 'environment');
  const radAlerts = activeFor(data, 'radiation');
  const events = sortNewest(data.events, e => e.timestamp).slice(0, 5);
  const delay = data.mission?.delay_minutes;
  return <><Heading eyebrow="MISSION OVERVIEW / 01" title="Mission Dashboard" description="A clear view of your crew, spacecraft and mission status." action={<button className="btn btn-outline" onClick={() => refresh().catch(() => {})}><RefreshCw size={15} /> REFRESH DATA</button>} />
    <div className="dashboard-intro"><div><div className="eyebrow">MISSION CONTROL <span className="eyebrow-slash">//</span> MARS TRANSIT</div><h2>Situational awareness,<br /><span>at a glance.</span></h2><p>Local mission data. Human judgment at every step.</p></div><div className="mission-graphic" aria-hidden="true"><span className="orbit-ring ring-a" /><span className="orbit-ring ring-b" /><span className="planet" /><span className="planet-dot" /><span className="orbit-label">TRANSIT / 01</span></div><div className="mission-number"><small>MISSION DAY</small><strong>{data.mission?.mission_day ?? '—'}</strong><span>{data.mission?.location || 'Location unavailable'}</span></div></div>
    <div className="overview-strip"><div><span className="over-icon"><Radio size={17} /></span><div><small>EARTH LINK</small><strong>{data.mission?.earth_connected === undefined ? 'UNAVAILABLE' : data.mission.earth_connected ? 'CONNECTED' : 'DISCONNECTED'}</strong><em>Simulated connection</em></div></div><div><span className="over-icon"><Clock3 size={17} /></span><div><small>COMMUNICATION DELAY</small><strong>{typeof delay === 'number' ? `${number(delay, 1)} min` : '—'}</strong><em>One way · {typeof delay === 'number' ? `${number(delay * 2, 1)} min round trip` : 'round trip unavailable'}</em></div></div><div><span className="over-icon"><ShieldAlert size={17} /></span><div><small>ACTIVE ALERTS</small><strong className={criticalCount ? 'text-red' : activeCount ? 'text-amber' : 'text-green'}>{activeCount} <i>{criticalCount} critical</i></strong><em>Requires human review</em></div></div><div><span className="over-icon"><Database size={17} /></span><div><small>LAST SYNCHRONIZATION</small><strong className="sync-value">{formatTime(data.mission?.last_sync)}</strong><em>Local / Earth link simulation</em></div></div></div>
    <div className="dashboard-orbit"><Suspense fallback={<div className="panel loading-panel" role="status">LOADING ILLUSTRATIVE MISSION VISUALIZATION…</div>}><MissionOrbit /></Suspense></div>
    <div className="dashboard-grid"><section className="panel crew-panel"><PanelTitle icon={HeartPulse} title="Crew overview" subtitle="Latest recorded physiological readings" action={<SectionAction onClick={() => navigate('Body')}>VIEW CREW</SectionAction>} /><div className="crew-list">{data.crew.length ? data.crew.map((crew, i) => { const hr = latestMetric(data, crew.id, 'heart_rate'); const spo2 = latestMetric(data, crew.id, 'spo2'); const alerts = activeFor(data, 'crew', crew.id); return <button className="crew-row" key={crew.id} onClick={() => navigate('Body', crew.id)}><CrewAvatar crew={crew} index={i} /><div className="crew-ident"><strong>{crew.name}</strong><span>{crew.role || 'Role not set'}</span></div><div className="crew-reading"><small>HEART RATE</small><strong><Value record={hr} /></strong></div><div className="crew-reading"><small>SpO₂</small><strong><Value record={spo2} /></strong></div><div className="crew-health"><Status tone={alerts.length ? severityTone(alerts) : alertsIncomplete ? 'muted' : severityTone(alerts)}>{alerts.length ? severityLabel(alerts) : alertsIncomplete ? 'ALERT STATUS UNKNOWN' : (crew.status || 'NO ACTIVE ALERTS').toUpperCase()}</Status><span>Updated {formatTime(crew.last_telemetry || latest(data.measurements.filter(m => m.crew_id === crew.id))?.timestamp)} · <Fresh timestamp={crew.last_telemetry || latest(data.measurements.filter(m => m.crew_id === crew.id))?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /></span></div><ChevronRight size={15} className="row-chevron" /></button>; }) : <Empty>No crew profiles recorded yet.</Empty>}</div></section>
    <section className="panel alert-panel"><PanelTitle icon={AlertTriangle} title="Priority alerts" subtitle="Active conditions requiring review" action={<SectionAction onClick={() => navigate('Alerts')}>VIEW ALL</SectionAction>} />{active.length ? <div className="alert-mini-list">{sortNewest(active, a => a.detected_at).sort((a, b) => (a.severity === 'CRITICAL' ? -1 : 0) - (b.severity === 'CRITICAL' ? -1 : 0)).slice(0, 3).map(a => <div className={`alert-mini ${a.severity === 'CRITICAL' ? 'critical' : 'warning'}`} key={a.id}><AlertCircle size={17} /><div><div><strong>{metricLabel(a.metric)}</strong><span>{a.severity}</span></div><p>{a.rule || 'Rule triggered'} · {a.value == null ? 'Value unavailable' : `${number(a.value, 2)} ${a.unit || ''}`}</p><small>{formatTime(a.detected_at)} · {a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}</small></div></div>)}</div> : <Empty>No active alerts in this snapshot. Continue to review incoming data.</Empty>}<button className="panel-bottom-link" onClick={() => navigate('Alerts')}>OPEN ALERT CENTER <ArrowRight size={14} /></button></section>
    <section className="panel systems-panel"><PanelTitle icon={Gauge} title="Spacecraft systems" subtitle="Latest locally recorded readings" action={<SectionAction onClick={() => navigate('Environment')}>DETAILS</SectionAction>} /><div className="system-tile-row"><div className="system-tile"><div className="system-tile-top"><span><Wind size={16} /> CABIN ENVIRONMENT</span><Status tone={envAlerts.length ? severityTone(envAlerts) : alertsIncomplete ? 'muted' : cabin ? 'green' : 'muted'}>{envAlerts.length ? severityLabel(envAlerts) : alertsIncomplete ? 'ALERT STATUS UNKNOWN' : cabin ? 'NO ACTIVE ALERTS' : 'MISSING'}</Status></div><strong><Value record={cabin} /></strong><small>CABIN TEMPERATURE · {formatTime(cabin?.timestamp)} · <Fresh timestamp={cabin?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /></small></div><div className="system-tile"><div className="system-tile-top"><span><RadiationIcon size={16} /> RADIATION EXPOSURE</span><Status tone={radAlerts.length ? severityTone(radAlerts) : alertsIncomplete ? 'muted' : data.radiation.length ? 'green' : 'muted'}>{radAlerts.length ? severityLabel(radAlerts) : alertsIncomplete ? 'ALERT STATUS UNKNOWN' : data.radiation.length ? 'NO ACTIVE ALERTS' : 'MISSING'}</Status></div><strong>{typeof data.mission?.radiation_total === 'number' ? <>{number(data.mission.radiation_total, 3)} <small>mSv</small></> : '—'}</strong><small>MISSION TOTAL · {data.radiation.length ? `${data.radiation.length} INCREMENTS IN SNAPSHOT` : 'NO RECORDED INCREMENTS'}</small></div></div></section>
    <section className="panel event-panel"><PanelTitle icon={Activity} title="Mission activity" subtitle="Recent recorded events" action={<SectionAction onClick={() => navigate('Log')}>VIEW LOG</SectionAction>} />{events.length ? <div className="event-list">{events.map(e => <div className="event-row" key={e.id}><span className="event-dot" /><div><strong>{pretty(e.category)}</strong><p>{e.detail}</p></div><time>{formatTime(e.timestamp)}</time></div>)}</div> : <Empty>No mission events recorded.</Empty>}</section></div>
    <div className="dashboard-briefing"><MissionBriefing data={data} /></div>
    <div className="view-footnote"><span><CircleDot size={13} /> ALL VALUES ARE SIMULATED AND LOCALLY RECORDED</span><span>DISPLAYED FRESHNESS WINDOW: {data.settings?.stale_after_minutes ?? 1440} MINUTES</span></div></>;
}

function FormNotice({ error, success }: { error: string; success?: string }) { return <>{error && <div className="notice error-notice" role="alert">{error}</div>}{success && <div className="notice success-notice" role="status">{success}</div>}</>; }
function CrewForm({ user, crew, onDone, refresh }: { user: User; crew?: Crew; onDone: () => void; refresh: () => Promise<void> }) {
  const [name, setName] = useState(crew?.name || ''); const [role, setRole] = useState(crew?.role || ''); const [status, setStatus] = useState(crew?.status || 'active');
  const [baseline, setBaseline] = useState(crew?.baseline || ''); const [history, setHistory] = useState(crew?.medical_history || ''); const [health, setHealth] = useState(crew?.current_health || '');
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [saved, setSaved] = useState(false);
  const medical = ['Medical Officer', 'Administrator'].includes(user.role);
  async function submit(e: React.FormEvent) { e.preventDefault(); setError(''); setBusy(true); try { const body: Record<string, string> = { name, role, status }; if (medical) Object.assign(body, { baseline, medical_history: history, current_health: health }); await api(crew ? `/crew/${crew.id}` : '/crew', { method: crew ? 'PATCH' : 'POST', body: JSON.stringify(body) }); setSaved(true); try { await refresh(); onDone(); } catch { setError('Profile saved, but the display could not refresh. Close this form and retry refresh; do not submit again.'); } } catch (e) { setError(e instanceof Error ? e.message : 'Could not save crew profile.'); } finally { setBusy(false); } }
  return <form className="form-card" onSubmit={submit}><div className="form-title"><div><span className="eyebrow">CREW MANAGEMENT</span><h3>{crew ? 'Edit crew profile' : 'Create crew profile'}</h3></div><button type="button" className="text-button" onClick={onDone}>CANCEL</button></div><FormNotice error={error} /><div className="form-grid"><label>NAME<input value={name} onChange={e => setName(e.target.value)} required /></label><label>MISSION ROLE<input value={role} onChange={e => setRole(e.target.value)} required /></label><label>STATUS<input value={status} onChange={e => setStatus(e.target.value)} required /></label>{medical && <><label>BASELINE<input value={baseline} onChange={e => setBaseline(e.target.value)} /></label><label>MEDICAL HISTORY<textarea value={history} onChange={e => setHistory(e.target.value)} /></label><label>CURRENT HEALTH<textarea value={health} onChange={e => setHealth(e.target.value)} /></label></>}</div><p className="form-help">Only simulated information. Changes are recorded by the local service.</p><button className="btn btn-primary" disabled={busy || saved}>{busy ? 'SAVING…' : saved ? 'SAVED' : 'SAVE PROFILE'} <ArrowRight size={15} /></button></form>;
}
function newReadingId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  if (!globalThis.crypto?.getRandomValues) throw new Error('Secure record IDs are unavailable in this browser.');
  const bytes = new Uint8Array(16); globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
}
function ReadingForm({ mode, data, crewId, refresh }: { mode: 'telemetry' | 'environment' | 'radiation'; data: Snapshot; crewId?: string; refresh: () => Promise<void> }) {
  const metrics = mode === 'environment' ? ENVIRONMENT : TELEMETRY;
  const [metric, setMetric] = useState(metrics[0].key); const [target, setTarget] = useState(crewId || data.crew[0]?.id || (mode === 'radiation' ? 'mission' : ''));
  const [value, setValue] = useState(''); const [source, setSource] = useState('Manual simulation'); const [timestamp, setTimestamp] = useState(localInputTime()); const [event, setEvent] = useState('');
  const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [busy, setBusy] = useState(false);
  const pending = useRef<{ fingerprint: string; id: string } | null>(null);
  useEffect(() => { if (crewId) setTarget(crewId); }, [crewId]);
  const selected = metrics.find(m => m.key === metric)!;
  async function submit(e: React.FormEvent) {
    e.preventDefault(); setBusy(true); setError(''); setSuccess('');
    try {
      if (value.trim() === '' || !Number.isFinite(Number(value))) throw new Error('Enter a valid numeric value.');
      if (!timestamp || Number.isNaN(new Date(timestamp).getTime())) throw new Error('Enter a valid timestamp.');
      const body: Record<string, unknown> = { value: Number(value), unit: mode === 'radiation' ? 'mSv' : selected.unit, source, timestamp: new Date(timestamp).toISOString() };
      if (mode === 'telemetry') { body.crew_id = target; body.metric = metric; }
      if (mode === 'environment') body.metric = metric;
      if (mode === 'radiation') { body.crew_id = target; if (event.trim()) body.event = event.trim(); }
      const fingerprint = JSON.stringify(body);
      if (pending.current?.fingerprint !== fingerprint) pending.current = { fingerprint, id: newReadingId() };
      body.id = pending.current.id;
      await api(`/${mode}`, json(body)); pending.current = null; setValue(''); setEvent(''); try { await refresh(); setSuccess('Record saved and mission data refreshed.'); } catch { setSuccess('Record saved, but refreshing the display failed. Use Refresh data before entering it again.'); }
    } catch (e) { setError(`${e instanceof Error ? e.message : 'Could not save the record.'}${pending.current ? ' The outcome may be uncertain: retry unchanged to reuse the record ID. Changing the entry creates a new ID.' : ''}`); } finally { setBusy(false); }
  }
  return <form className="form-card reading-form" onSubmit={submit}><div className="form-title"><div><span className="eyebrow">MANUAL INPUT / SIMULATED</span><h3>Record {mode === 'telemetry' ? 'telemetry' : mode === 'radiation' ? 'radiation dose increment' : 'environment reading'}</h3></div></div><FormNotice error={error} success={success} /><div className="form-grid">
    {mode !== 'environment' && <label>{mode === 'radiation' ? 'ASSOCIATED EXPOSURE' : 'CREW MEMBER'}<select required disabled={busy} value={target} onChange={e => setTarget(e.target.value)}>{mode === 'radiation' && <option value="mission">Mission</option>}{!target && <option value="">Select crew</option>}{data.crew.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}
    {mode !== 'radiation' && <label>METRIC<select disabled={busy} value={metric} onChange={e => setMetric(e.target.value)}>{metrics.map(m => <option key={m.key} value={m.key}>{m.label}</option>)}</select></label>}
    <label>VALUE <span className="field-unit">({mode === 'radiation' ? 'mSv' : selected.unit})</span><input type="number" step="any" min={mode === 'radiation' ? 0 : undefined} required disabled={busy} value={value} onChange={e => setValue(e.target.value)} placeholder="Enter reading" /></label><label>SOURCE<input required disabled={busy} value={source} onChange={e => setSource(e.target.value)} /></label><label>MEASURED AT <span className="field-unit">(local time)</span><input type="datetime-local" required disabled={busy} value={timestamp} onChange={e => setTimestamp(e.target.value)} /></label>{mode === 'radiation' && <label>EVENT <span className="field-unit">(optional)</span><input disabled={busy} value={event} onChange={e => setEvent(e.target.value)} placeholder="Event description" /></label>}</div><p className="form-help">Units are attached to each record. Times are converted to UTC; measurements are validated by the server. Retry an uncertain submission unchanged while this form remains open to avoid a duplicate.</p><button className="btn btn-primary" disabled={busy || (mode !== 'environment' && !target)}><Plus size={15} /> {busy ? 'SAVING…' : 'SAVE READING'}</button></form>;
}

const REGIONS: { name: string; description: string; metrics: string[] }[] = [
  { name: 'Head', description: 'Rest and recovery', metrics: ['sleep'] }, { name: 'Chest', description: 'Cardiovascular and respiratory', metrics: ['heart_rate', 'bp_systolic', 'bp_diastolic', 'spo2', 'respiratory_rate'] }, { name: 'Core', description: 'Temperature and hydration', metrics: ['temperature', 'hydration'] }, { name: 'Body composition', description: 'Weight and composition', metrics: ['weight', 'body_fat'] },
];
export function BodyView({ user, data, refresh, initialCrewId }: ViewProps & { initialCrewId?: string }) {
  const [crewId, setCrewId] = useState(initialCrewId || data.crew[0]?.id || ''); const [region, setRegion] = useState('Chest'); const [editing, setEditing] = useState<'create' | 'edit' | null>(null); const [showForm, setShowForm] = useState(false);
  useEffect(() => { if (!data.crew.some(c => c.id === crewId)) setCrewId(data.crew[0]?.id || ''); }, [data.crew, crewId]);
  const crew = data.crew.find(c => c.id === crewId); const chosen = REGIONS.find(r => r.name === region)!;
  const records = crew ? data.measurements.filter(m => m.crew_id === crew.id) : []; const updated = crew?.last_telemetry || latest(records)?.timestamp;
  return <><Heading eyebrow="CREW HEALTH / 02" title="Body telemetry" description="Review an individual crew member’s most recent recorded measurements." action={canManageCrew(user) ? <button className="btn btn-outline" onClick={() => setEditing('create')}><Plus size={15} /> ADD CREW MEMBER</button> : undefined} />
    {editing && <CrewForm user={user} crew={editing === 'edit' ? crew : undefined} onDone={() => setEditing(null)} refresh={refresh} />}
    {!data.crew.length ? <section className="panel"><Empty>No crew profiles available. {canManageCrew(user) ? 'Create a simulated crew member to begin.' : 'Ask an authorized operator to add a crew member.'}</Empty></section> : <><div className="body-toolbar"><label>CREW MEMBER<select value={crewId} onChange={e => setCrewId(e.target.value)}>{data.crew.map(c => <option value={c.id} key={c.id}>{c.name} / {c.role}</option>)}</select></label><div className="body-toolbar-status"><span>LAST TELEMETRY</span><strong>{formatDate(updated)}</strong><Fresh timestamp={updated} staleMinutes={data.settings?.stale_after_minutes} /></div><div className="toolbar-actions">{canManageCrew(user) && <button className="btn btn-outline" onClick={() => setEditing('edit')}>EDIT PROFILE</button>}{canRecord(user) && <button className="btn btn-primary" onClick={() => setShowForm(!showForm)}><Plus size={15} /> {showForm ? 'CLOSE ENTRY' : 'RECORD TELEMETRY'}</button>}</div></div>
    {showForm && <ReadingForm mode="telemetry" data={data} crewId={crewId} refresh={refresh} />}
    <div className="body-layout"><section className="panel body-figure-panel"><PanelTitle icon={HeartPulse} title="Body map" subtitle="Select a region to inspect related measurements" /><div className="body-figure"><div className="body-gridline" /><img src="/body.png" alt="Illustration of the human body for selecting telemetry regions" /><div className="figure-label top-left">ANTERIOR VIEW<br /><span>CREW PHYSIOLOGY</span></div><div className="figure-label bottom-right">FIG. 01<br /><span>SELECT A REGION</span></div></div><div className="region-tabs" role="group" aria-label="Body region">{REGIONS.map(r => <button key={r.name} className={region === r.name ? 'selected' : ''} aria-pressed={region === r.name} onClick={() => setRegion(r.name)}>{r.name}</button>)}</div></section>
    <div className="body-details"><section className="panel profile-panel"><div className="profile-header">{crew && <CrewAvatar crew={crew} />}<div><span className="eyebrow">CREW PROFILE</span><h2>{crew?.name}</h2><p>{crew?.role} · ID {crew?.id}</p></div><Status tone={activeFor(data, 'crew', crewId).length ? severityTone(activeFor(data, 'crew', crewId)) : hasOmittedActiveAlerts(data) ? 'muted' : 'green'}>{activeFor(data, 'crew', crewId).length ? severityLabel(activeFor(data, 'crew', crewId)) : hasOmittedActiveAlerts(data) ? 'ALERT STATUS UNKNOWN' : (crew?.status || 'NO ACTIVE ALERTS').toUpperCase()}</Status></div></section><section className="panel"><PanelTitle icon={Activity} title={`${region} readings`} subtitle={chosen.description} /><div className="vitals-grid">{chosen.metrics.map(key => { const m = TELEMETRY.find(x => x.key === key)!; const reading = latest(records.filter(r => r.metric === key)); const alerts = activeFor(data, 'crew', crewId, key); return <div className="vital-card" key={key}><div><span>{m.label.toUpperCase()}</span>{alerts.length > 0 && <Status tone={!alerts.length && hasOmittedActiveAlerts(data) ? 'muted' : severityTone(alerts)}>{!alerts.length && hasOmittedActiveAlerts(data) ? 'ALERT STATUS UNKNOWN' : severityLabel(alerts)}</Status>}</div><strong><Value record={reading} /></strong><small>{reading ? `${formatTime(reading.timestamp)} · ${reading.source}` : 'No valid reading recorded'}</small><Fresh timestamp={reading?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /></div>; })}</div></section><section className="panel"><PanelTitle title="All telemetry" subtitle="Latest reading per metric · select a region to focus above" /><div className="compact-table-wrap"><table className="compact-table"><thead><tr><th>METRIC</th><th>VALUE</th><th>RECORDED</th><th>STATE</th></tr></thead><tbody>{TELEMETRY.map(m => { const r = latest(records.filter(v => v.metric === m.key)); return <tr key={m.key}><td>{m.label}</td><td><Value record={r} /></td><td>{formatTime(r?.timestamp)}</td><td><Fresh timestamp={r?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /></td></tr>; })}</tbody></table></div></section></div></div></>}</>;
}
type Point = ChartPoint;
const COLORS = ['#56d7e8', '#f4b65d', '#9f9bff', '#77dca8', '#f28496', '#88a8e5'];
const localDateTime = (date: Date) => new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
function Chart({ points, unit, dailyAlerts = false }: { points: Point[]; unit: string; dailyAlerts?: boolean }) {
  const chart = useMemo(() => prepareChart(points), [points]);
  if (!points.length) return <Empty>No stored readings match these filters.</Empty>;
  if (!chart.validCount) return <Empty>No valid timestamps or values are available to chart.</Empty>;
  const { xmin, xmax, ymin, ymax } = chart;
  const range = ymax - ymin; const pad = range > 0 ? range * .15 : Math.abs(ymax) * .1 || 1; const low = ymin - pad, high = ymax + pad;
  const x = (t: number) => 62 + (xmax === xmin ? 0.5 : (t - xmin) / (xmax - xmin)) * 710; const y = (v: number) => 205 - ((v - low) / (high - low)) * 170;
  return <div className="chart-wrap"><div className="chart-legend">{chart.plotted.map(({ name }, i) => <span key={name}><i style={{ background: COLORS[i % COLORS.length] }} />{name}</span>)}</div><svg className="line-chart" viewBox="0 0 800 250" role="img" aria-label={`Available ${unit || 'unit unspecified'} readings over time across ${chart.plotted.map(s => s.name).join(', ')}`} preserveAspectRatio="none">{[0, 1, 2, 3, 4].map(i => { const yy = 35 + i * 42.5; const val = high - i * (high - low) / 4; return <g key={i}><line x1="62" y1={yy} x2="772" y2={yy} className="chart-grid" /><text x="50" y={yy + 4} textAnchor="end">{formatTrendAxis(val, (high - low) / 4)}</text></g>; })}{chart.plotted.map(({ name, samples }, i) => <g key={name}>{chartSegments(points.filter(p => p.series === name), samples, dailyAlerts).map((segment, j) => <polyline key={j} fill="none" stroke={COLORS[i % COLORS.length]} strokeWidth="2.5" points={segment.map(p => `${x(p.time)},${y(p.value)}`).join(' ')} />)}{samples.map((p, j) => <circle key={j} cx={x(p.time)} cy={y(p.value)} r="3.5" fill={COLORS[i % COLORS.length]}><title>{name}: {formatTrendValue(p.value)} {p.unit}, {formatDate(p.timestamp)}</title></circle>)}</g>)}<text x="62" y="234">{formatDate(new Date(xmin).toISOString())}</text><text x="772" y="234" textAnchor="end">{formatDate(new Date(xmax).toISOString())}</text></svg><div className="chart-caption">{chart.displayedCount} ACTUAL POINTS SHOWN / {chart.validCount} VALID {dailyAlerts ? 'DAYS' : 'RECORDS'} · {unit || 'UNIT NOT RECORDED'} · UTC{chart.displayedCount < chart.validCount && ' · SAMPLED (BUCKET MIN/MAX)'}</div><p className="form-help">{dailyAlerts ? 'Days with no loaded alerts are not plotted or joined.' : 'Lines are visual guides only. Breaks mark intervals over three times the median observed spacing, when enough readings exist; they do not establish an expected cadence.'}</p>{chart.totalSeries > chart.plotted.length && <p className="form-help">Showing {chart.plotted.length} of {chart.totalSeries} series to limit rendering. Select a crew member to narrow the chart.</p>}</div>;
}
export function TrendsView({ data }: ViewProps) {
  const [metric, setMetric] = useState('heart_rate'); const [crew, setCrew] = useState('all'); const [period, setPeriod] = useState('all');
  const [reload, setReload] = useState(0); const [chosenUnit, setChosenUnit] = useState('');
  const [draft, setDraft] = useState(() => { const end = new Date(); return { since: localDateTime(new Date(end.getTime() - 7 * 86_400_000)), until: localDateTime(end) }; });
  const [customRange, setCustomRange] = useState(() => ({ since: new Date(draft.since).toISOString(), until: new Date(draft.until).toISOString() }));
  const [rangeError, setRangeError] = useState('');
  const [state, setState] = useState<{ key: string; phase: 'loading' | 'ready' | 'error'; history?: TrendHistory; error?: string } | null>(null);
  // Environment has no crew dimension. Snapshot polling must not trigger history reads.
  const filterCrew = metric.startsWith('env:') ? 'all' : crew;
  const customSince = period === 'custom' ? customRange.since : undefined; const customUntil = period === 'custom' ? customRange.until : undefined;
  const key = JSON.stringify([metric, filterCrew, period, customSince, customUntil, reload]);
  useEffect(() => {
    const controller = new AbortController(); let disposed = false, timedOut = false; let timeout: number | undefined;
    setState({ key, phase: 'loading' });
    const debounce = window.setTimeout(() => {
      const token = sessionStorage.getItem(TOKEN_KEY);
      timeout = window.setTimeout(() => { timedOut = true; controller.abort(); if (!disposed) setState({ key, phase: 'error', error: 'History request timed out. Retry or choose a shorter range.' }); }, 45_000);
      void loadTrendHistory({ metric, crew: filterCrew, period, since: customSince, until: customUntil }, { signal: controller.signal, token, onUnauthorized: () => {
        if (sessionStorage.getItem(TOKEN_KEY) === token) { sessionStorage.removeItem(TOKEN_KEY); sessionStorage.removeItem(EXPIRY_KEY); window.dispatchEvent(new Event('checkpoint:session-expired')); }
      } }).then(history => {
        if (!disposed && !controller.signal.aborted) setState({ key, phase: 'ready', history });
      }).catch(error => {
        if (!disposed) setState({ key, phase: 'error', error: timedOut ? 'History request timed out. Retry or choose a shorter range.' : error instanceof Error ? error.message : 'Could not load history.' });
        controller.abort();
      }).finally(() => window.clearTimeout(timeout));
    }, 200);
    return () => { disposed = true; window.clearTimeout(debounce); window.clearTimeout(timeout); controller.abort(); };
  }, [key, metric, filterCrew, period, customSince, customUntil]);
  function applyCustomRange() {
    const since = new Date(draft.since); const until = new Date(draft.until);
    if (!draft.since || !draft.until || !Number.isFinite(since.getTime()) || !Number.isFinite(until.getTime()) || since.getTime() > until.getTime()) {
      setRangeError('Enter a valid start and end; start must not be after end.'); return;
    }
    setRangeError(''); setCustomRange({ since: since.toISOString(), until: until.toISOString() });
  }
  const current = state?.key === key ? state : null;
  const history = current?.phase === 'ready' ? current.history : undefined;
  const namesKey = JSON.stringify(data.crew.map(c => [c.id, c.name]));
  const names = useMemo(() => {
    const entries = JSON.parse(namesKey) as [string, string][];
    return Object.fromEntries(entries.map(([id, name]) => [id, entries.filter(([, n]) => n === name).length > 1 || name === 'Mission' ? `${name} (${id})` : name]));
  }, [namesKey]);
  const { points, skipped } = useMemo(() => {
    const result: Point[] = []; let invalid = 0; const counts = new Map<string, number>();
    for (const record of history?.records ?? []) {
      if (metric === 'alerts') {
        const time = Date.parse((record as Alert).detected_at);
        if (!Number.isFinite(time)) { invalid++; continue; }
        const day = new Date(time).toISOString().slice(0, 10);
        counts.set(day, (counts.get(day) || 0) + 1);
        continue;
      }
      const reading = record as Measurement | Radiation | Environment;
      if (!Number.isFinite(Date.parse(reading.timestamp)) || typeof reading.value !== 'number' || !Number.isFinite(reading.value)) { invalid++; continue; }
      let series: string;
      if (metric.startsWith('env:')) series = metricLabel((reading as Environment).metric);
      else {
        const id = (reading as Measurement | Radiation).crew_id;
        series = id === 'mission' ? 'Mission' : names[id] || id;
        if (metric === 'blood_pressure') series += ` / ${(reading as Measurement).metric === 'bp_systolic' ? 'systolic' : 'diastolic'}`;
      }
      result.push({ timestamp: reading.timestamp, value: reading.value, series, unit: typeof reading.unit === 'string' ? reading.unit : '' });
    }
    counts.forEach((value, day) => result.push({ timestamp: `${day}T00:00:00Z`, value, series: 'Alerts per UTC day', unit: 'alerts' }));
    return { points: result, skipped: invalid };
  }, [history, metric, names]);
  const units = useMemo(() => Array.from(new Set(points.map(p => p.unit))).sort(), [points]);
  const unit = units.includes(chosenUnit) ? chosenUnit : units[0] || '';
  const shown = useMemo(() => points.filter(p => p.unit === unit), [points, unit]);
  const title = metric === 'blood_pressure' ? 'Blood pressure' : metric === 'dose' ? 'Radiation dose increments' : metric === 'alerts' ? 'Alert frequency' : metricLabel(metric.replace('env:', ''));
  return <><Heading eyebrow="HISTORICAL ANALYSIS / 03" title="Trends & analysis" description="Explore stored history and compare recorded observations over time, not predictions." /><div className="notice info-notice">SIMULATION ONLY / NOT FOR CLINICAL USE. Records and alert outputs require human review. History is loaded on filter changes or refresh, not on every snapshot update.</div><section className="panel"><div className="filter-bar"><label>METRIC<select value={metric} onChange={e => { const next = e.target.value; setMetric(next); if (next !== 'dose' && crew === 'mission') setCrew('all'); }}><optgroup label="Crew telemetry">{TELEMETRY.filter(m => !m.key.startsWith('bp_')).map(m => <option key={m.key} value={m.key}>{m.label}</option>)}<option value="blood_pressure">Blood pressure (systolic / diastolic)</option></optgroup><optgroup label="Spacecraft"><option value="dose">Radiation dose increments</option>{ENVIRONMENT.map(m => <option key={m.key} value={`env:${m.key}`}>{m.label}</option>)}</optgroup><optgroup label="Events"><option value="alerts">Alert frequency</option></optgroup></select></label><label>{metric === 'dose' ? 'EXPOSURE SCOPE' : 'CREW'}<select value={filterCrew} onChange={e => setCrew(e.target.value)} disabled={metric.startsWith('env:')}><option value="all">{metric === 'alerts' ? 'All alert types' : metric === 'dose' ? 'All exposures / comparison' : 'All crew / comparison'}</option>{data.crew.map(c => <option value={c.id} key={c.id}>{names[c.id]}</option>)}{metric === 'dose' && <option value="mission">Mission</option>}</select></label><label>TIME RANGE<select value={period} onChange={e => setPeriod(e.target.value)}><option value="all">All stored history through now</option><option value="1">Past 24 hours</option><option value="7">Past 7 days</option><option value="30">Past 30 days</option><option value="90">Past 90 days</option><option value="custom">Custom interval</option></select></label><button type="button" className="btn btn-outline" onClick={() => setReload(n => n + 1)}><RefreshCw size={15} /> REFRESH HISTORY</button></div>
    {period === 'custom' && <><div className="filter-bar"><label>FROM (LOCAL TIME)<input type="datetime-local" value={draft.since} onChange={e => { setDraft(d => ({ ...d, since: e.target.value })); setRangeError(''); }} /></label><label>THROUGH (LOCAL TIME)<input type="datetime-local" value={draft.until} onChange={e => { setDraft(d => ({ ...d, until: e.target.value })); setRangeError(''); }} /></label><button type="button" className="btn btn-outline" onClick={applyCustomRange}>APPLY INTERVAL</button></div><p className="form-help">Dates are entered in local time and queried inclusively in UTC. Changes apply only after selecting Apply interval.</p>{rangeError && <div className="notice error-notice" role="alert">{rangeError}</div>}</>}
    <div role="status" aria-live="polite" className="notice info-notice">{!current || current.phase === 'loading' ? 'Loading stored history…' : current.phase === 'ready' && history ? `Loaded ${history.records.length.toLocaleString()} stored records${history.since ? ` from ${formatDate(history.since)}` : ''} through ${formatDate(history.loadedAt)}. ${period === 'custom' ? 'Refresh to reload this interval.' : 'Refresh to include newer records.'}` : 'History could not be loaded.'}</div>
    {current?.phase === 'error' && <div className="notice error-notice" role="alert">{current.error} <button type="button" className="text-button" onClick={() => setReload(n => n + 1)}>Retry history</button></div>}
    {history && history.truncatedStreams.length > 0 && <div className="notice error-notice" role="status">Partial history: the newest records were loaded up to the limit ({TREND_RECORD_CAP.toLocaleString()} records, or {(TREND_RECORD_CAP / 2).toLocaleString()} per blood-pressure component). More records exist for {history.truncatedStreams.join(', ')}. Narrow the time range or crew; chart, table and alert counts may be incomplete.</div>}
    {history?.changedDuringLoad && <div className="notice error-notice" role="status">The archive changed while pages were loading; results may contain gaps. Refresh history for a more consistent view.</div>}
    {history && <p className="form-help">Pages have a fixed end time, but the archive can change during loading. {metric === 'alerts' ? 'All types include crew, environmental and radiation alerts; selecting a crew member includes alerts associated with that ID. Counts include active and resolved alerts; boundary days can be partial.' : metric === 'dose' ? 'Values are dose increments, not dose rates; all exposures include mission-tagged and individual records.' : metric.startsWith('env:') ? 'Environment readings apply to the spacecraft, not an individual crew member.' : 'Select all crew to compare individual series.'} {skipped > 0 && `${skipped} record(s) with invalid timestamps or values were omitted.`}</p>}
    {history && units.length > 1 && <div className="filter-bar"><label>DISPLAY UNIT<select value={unit} onChange={e => setChosenUnit(e.target.value)}>{units.map(u => <option value={u} key={u}>{u || 'Unit not recorded'}</option>)}</select></label><span>Different recorded units are displayed separately; no conversion is assumed.</span></div>}
    <PanelTitle icon={Activity} title={title} subtitle={metric === 'alerts' ? 'Stored alert counts by UTC detection day · days with no alerts are not plotted' : 'Actual stored records · hover over points for details'} />{history && <Chart points={shown} unit={unit} dailyAlerts={metric === 'alerts'} />}</section>
    {history && <section className="panel spacing-top"><PanelTitle title={metric === 'alerts' ? 'Recorded daily counts' : 'Recorded values'} subtitle={`Most recent 25 ${metric === 'alerts' ? 'days with alerts' : 'loaded records'}${units.length > 1 ? ' in the selected unit' : ''}`} /><div className="compact-table-wrap"><table className="compact-table"><thead><tr><th scope="col">RECORDED / UTC</th><th scope="col">SERIES</th><th scope="col">VALUE</th></tr></thead><tbody>{sortNewest(shown, p => p.timestamp).slice(0, 25).map((p, i) => <tr key={`${p.timestamp}-${p.series}-${i}`}><td>{formatDate(p.timestamp)}</td><td>{p.series}</td><td>{formatTrendValue(p.value)} {p.unit}</td></tr>)}</tbody></table></div>{!shown.length && <Empty>No valid records in this range.</Empty>}</section>}</>;
}

function RuleText({ rule }: { rule?: Record<string, any> }) {
  if (!rule) return <span>Rule not configured</span>;
  return <span>Configured range {number(rule.min, 3)}–{number(rule.max, 3)} {rule.unit}; critical below {number(rule.critical_min, 3)} / above {number(rule.critical_max, 3)} {rule.unit}.</span>;
}
function SystemAlertPanel({ user, data, refresh, type }: ViewProps & { type: 'environment' | 'radiation' }) {
  const alerts = sortNewest(activeFor(data, type), a => a.detected_at);
  const [error, setError] = useState(''); const [busy, setBusy] = useState('');
  async function act(alert: Alert, action: 'acknowledge' | 'resolve') {
    setBusy(`${alert.id}:${action}`); setError('');
    try { await api(`/alerts/${alert.id}/${action}`, { method: 'POST' }); try { await refresh(); } catch { setError('Alert action was saved, but the display could not refresh. Retry refresh.'); } }
    catch (e) { setError(e instanceof Error ? e.message : 'Could not update alert.'); }
    finally { setBusy(''); }
  }
  return <section className="panel spacing-top"><PanelTitle icon={AlertTriangle} title="Active rule alerts" subtitle="Trigger details and operator review" /><div className="system-alerts"><FormNotice error={error} />{alerts.length ? alerts.map(a => <article className="system-alert-row" key={a.id}><div><Status tone={a.severity === 'CRITICAL' ? 'red' : a.severity === 'WARNING' ? 'amber' : 'cyan'}>{a.severity}</Status><strong>{metricLabel(a.metric)}</strong><p>{a.rule || 'Rule triggered'} · {a.value == null ? 'Value unavailable' : `${number(a.value, 3)} ${a.unit || ''}`} · {formatTime(a.detected_at)} · {a.resolved ? 'RESOLVED' : a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}</p></div>{canReviewAlerts(user, a.entity_type) && <div className="alert-actions">{!a.acknowledged && <button className="btn btn-outline" disabled={!!busy} onClick={() => act(a, 'acknowledge')}>ACKNOWLEDGE</button>}<button className="btn btn-outline" disabled={!!busy} onClick={() => act(a, 'resolve')}>RESOLVE</button></div>}</article>) : <Empty>No active {type} alerts in this snapshot.</Empty>}</div></section>;
}
function HistoryTable({ records, crewNames, staleMinutes }: { records: (Radiation | Environment)[]; crewNames?: Record<string, string>; staleMinutes?: number }) { return records.length ? <div className="compact-table-wrap"><table className="compact-table"><thead><tr><th>RECORDED</th><th>{crewNames ? 'ASSOCIATION' : 'METRIC'}</th><th>VALUE</th><th>SOURCE / EVENT</th><th>FRESHNESS</th></tr></thead><tbody>{sortNewest(records, r => r.timestamp).slice(0, 50).map(r => <tr key={r.id}><td>{formatTime(r.timestamp)}</td><td>{crewNames ? crewNames[(r as Radiation).crew_id] || pretty((r as Radiation).crew_id) : metricLabel((r as Environment).metric)}</td><td>{number(r.value, 3)} {r.unit}</td><td>{r.source}{(r as Radiation).event ? ` · ${(r as Radiation).event}` : ''}</td><td><Fresh timestamp={r.timestamp} staleMinutes={staleMinutes} /></td></tr>)}</tbody></table></div> : <Empty>No records available yet.</Empty>; }
export function RadiationView({ user, data, refresh }: ViewProps) {
  const [target, setTarget] = useState('all'); const [showForm, setShowForm] = useState(false);
  const records = data.radiation.filter(r => target === 'all' || r.crew_id === target); const total = records.reduce((sum, r) => sum + (Number.isFinite(r.value) ? r.value : 0), 0); const day = new Date().toISOString().slice(0, 10); const daily = records.filter(r => r.timestamp.startsWith(day)).reduce((sum, r) => sum + (Number.isFinite(r.value) ? r.value : 0), 0); const last = latest(records); const alerts = activeFor(data, 'radiation'); const names = Object.fromEntries(data.crew.map(c => [c.id, c.name]));
  return <><Heading eyebrow="SPACECRAFT SYSTEMS / 07" title="Radiation exposure" description="Track recorded dose increments and review exposure alerts." action={canRecord(user) ? <button className="btn btn-primary" onClick={() => setShowForm(!showForm)}><Plus size={15} /> {showForm ? 'CLOSE ENTRY' : 'RECORD DOSE'}</button> : undefined} />{showForm && <ReadingForm mode="radiation" data={data} refresh={refresh} />}<div className="filter-bar standalone-filter"><label>EXPOSURE SCOPE<select value={target} onChange={e => setTarget(e.target.value)}><option value="all">All recorded increments</option><option value="mission">Mission-tagged</option>{data.crew.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><Status tone={!alerts.length && hasOmittedActiveAlerts(data) ? 'muted' : severityTone(alerts)}>{!alerts.length && hasOmittedActiveAlerts(data) ? 'ALERT STATUS UNKNOWN' : severityLabel(alerts)}</Status></div><div className="summary-grid"><div className="panel summary-card"><small>SNAPSHOT EXPOSURE SUBTOTAL</small><strong>{records.length ? number(total, 3) : '—'} <span>mSv</span></strong><p>Sum of selected increments in this snapshot</p></div><div className="panel summary-card"><small>TODAY'S EXPOSURE / UTC</small><strong>{records.length ? number(daily, 3) : '—'} <span>mSv</span></strong><p>Snapshot increments on {day}</p></div><div className="panel summary-card"><small>LATEST INCREMENT</small><strong><Value record={last} digits={3} /></strong><p>{formatTime(last?.timestamp)} · <Fresh timestamp={last?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /></p></div></div><div className="notice info-notice">Subtotals sum selected snapshot increments and can omit older records; mission-tagged and individual records are not deduplicated. Alerts reflect configured server rules, not medical advice. <RuleText rule={data.settings?.thresholds?.radiation_cumulative} /></div><section className="panel"><PanelTitle icon={RadiationIcon} title="Exposure history" subtitle="Snapshot dose increments · up to 50 shown, not an estimated dose rate" /><HistoryTable records={records} crewNames={names} staleMinutes={data.settings?.stale_after_minutes} /></section><SystemAlertPanel user={user} data={data} refresh={refresh} type="radiation" /></>;
}
export function EnvironmentView({ user, data, refresh }: ViewProps) {
  const [showForm, setShowForm] = useState(false); const alerts = activeFor(data, 'environment');
  return <><Heading eyebrow="SPACECRAFT SYSTEMS / 08" title="Environment" description="Monitor the latest recorded spacecraft conditions and local rule alerts." action={canRecord(user) ? <button className="btn btn-primary" onClick={() => setShowForm(!showForm)}><Plus size={15} /> {showForm ? 'CLOSE ENTRY' : 'RECORD READING'}</button> : undefined} />{showForm && <ReadingForm mode="environment" data={data} refresh={refresh} />}<div className="section-kicker"><span>ENVIRONMENTAL MONITORING</span><Status tone={!alerts.length && hasOmittedActiveAlerts(data) ? 'muted' : severityTone(alerts)}>{!alerts.length && hasOmittedActiveAlerts(data) ? 'ALERT STATUS UNKNOWN' : severityLabel(alerts)}</Status></div><div className="environment-grid">{ENVIRONMENT.map(m => { const r = latestEnv(data, m.key); const matching = activeFor(data, 'environment', undefined, m.key); return <section className="panel env-card" key={m.key}><div><span className="env-icon">{m.key === 'cabin_temperature' ? <Thermometer size={19} /> : m.key === 'radiation' ? <RadiationIcon size={19} /> : <Wind size={19} />}</span><Status tone={matching.length ? severityTone(matching) : hasOmittedActiveAlerts(data) ? 'muted' : r ? 'green' : 'muted'}>{matching.length ? severityLabel(matching) : hasOmittedActiveAlerts(data) ? 'ALERT STATUS UNKNOWN' : r ? 'NO ACTIVE ALERTS' : 'MISSING'}</Status></div><h2>{m.label}</h2><strong><Value record={r} digits={3} /></strong><p>{r ? `Updated ${formatTime(r.timestamp)} · ${r.source}` : 'No reading recorded'}</p><Fresh timestamp={r?.timestamp} staleMinutes={data.settings?.stale_after_minutes} /><p className="rule-text"><RuleText rule={data.settings?.thresholds?.[m.key]} /></p></section>; })}</div><section className="panel spacing-top"><PanelTitle title="Environmental history" subtitle="Most recent measurements in this snapshot · up to 50 shown" /><HistoryTable records={data.environment} staleMinutes={data.settings?.stale_after_minutes} /></section><SystemAlertPanel user={user} data={data} refresh={refresh} type="environment" /></>;
}
export function AlertsView({ user, data, refresh }: ViewProps) {
  const [filter, setFilter] = useState('active'); const [error, setError] = useState(''); const [busy, setBusy] = useState('');
  const rows = sortNewest(data.alerts.filter(a => filter === 'all' || (filter === 'active' ? !a.resolved : a.resolved)), a => a.detected_at); const names = Object.fromEntries(data.crew.map(c => [c.id, c.name]));
  async function act(a: Alert, action: 'acknowledge' | 'resolve') { setError(''); setBusy(`${a.id}:${action}`); try { await api(`/alerts/${a.id}/${action}`, { method: 'POST' }); try { await refresh(); } catch { setError('Alert action was saved, but the display could not refresh. Retry refresh.'); } } catch (e) { setError(e instanceof Error ? e.message : 'Could not update alert.'); } finally { setBusy(''); } }
  const active = data.alerts.filter(a => !a.resolved); const alertWindow = snapshotWindow(data, 'alerts'); const incomplete = hasOmittedActiveAlerts(data); return <><Heading eyebrow="MISSION SAFETY / 09" title="Alert center" description="Review triggered rules and record human acknowledgement or resolution." /><div className="alert-summary"><div><span>ACTIVE</span><strong>{alertWindow?.active ?? active.length}</strong></div><div><span>CRITICAL</span><strong className="text-red">{alertWindow?.active_critical ?? active.filter(a => a.severity === 'CRITICAL').length}</strong></div><div><span>{incomplete ? 'VISIBLE WARNING' : 'WARNING'}</span><strong className="text-amber">{active.filter(a => a.severity === 'WARNING').length}</strong></div><div><span>{incomplete ? 'VISIBLE UNACKNOWLEDGED' : 'UNACKNOWLEDGED'}</span><strong>{active.filter(a => !a.acknowledged).length}</strong></div></div><div className="notice info-notice"><ShieldAlert size={16} /> Alerts are simulated rule outputs, not diagnoses. Guidance is unapproved and requires human review.</div><FormNotice error={error} /><section className="panel"><PanelTitle icon={AlertCircle} title="Alert records" subtitle="Snapshot trigger values, rule details and recorded disposition" action={<label className="inline-filter"><span className="sr-only">Filter alerts</span><select value={filter} onChange={e => setFilter(e.target.value)}><option value="active">Active alerts</option><option value="resolved">Resolved alerts</option><option value="all">All alerts</option></select></label>} />{rows.length ? <div className="alerts-list">{rows.map(a => <article className={`alert-record severity-${a.severity.toLowerCase()}`} key={a.id}><div className="alert-record-main"><div className="alert-icon"><AlertTriangle size={18} /></div><div><div className="alert-record-title"><h3>{metricLabel(a.metric)}</h3><Status tone={a.severity === 'CRITICAL' ? 'red' : a.severity === 'WARNING' ? 'amber' : 'cyan'}>{a.severity}</Status><span className="alert-state">{a.resolved ? 'RESOLVED' : a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}</span></div><p>{pretty(a.entity_type)} · {names[a.entity_id] || a.entity_id || 'Mission'} · Detected {formatDate(a.detected_at)}</p><div className="alert-trigger"><span>TRIGGER <b>{a.value == null ? 'Unavailable' : `${number(a.value, 3)} ${a.unit || ''}`}</b></span><span>RULE <b>{a.rule || 'Not specified'}</b></span></div>{a.guidance && <p className="guidance">Human review: {a.guidance}</p>}</div></div>{canReviewAlerts(user, a.entity_type) && !a.resolved && <div className="alert-actions">{!a.acknowledged && <button className="btn btn-outline" disabled={!!busy} onClick={() => act(a, 'acknowledge')}>{busy === `${a.id}:acknowledge` ? 'SAVING…' : 'ACKNOWLEDGE'}</button>}<button className="btn btn-outline" disabled={!!busy} onClick={() => act(a, 'resolve')}><Check size={14} /> {busy === `${a.id}:resolve` ? 'SAVING…' : 'RESOLVE'}</button></div>}</article>)}</div> : <Empty>No {filter === 'all' ? '' : filter} alerts in this snapshot.</Empty>}</section></>;
}
